export default meta;
type Story = StoryObj<typeof Tabs>;

export const Basic: Story = {
  tags: ["visual-test"],
  parameters: { docs: { source: { type: "code" } } },
  render: (args) => {
    const [selectedTab, setSelectedTab] = useState(0);
    return (
      <Tabs
        value={selectedTab}
        onChange={(event, value) => setSelectedTab(value)}
        {...args}
      >
        <Tab>Tab label 1</Tab>
        <Tab>Tab label 2</Tab>
        <Tab disabled>Tab label 3</Tab>
        <Tab>Tab label 4</Tab>
      </Tabs>
    );
  },
};

